local ScreenGui = Instance.new("ScreenGui")
ScreenGui.Name = "dontskidthisufaggotskidders"
ScreenGui.Parent = game.Players.LocalPlayer:WaitForChild("PlayerGui")
ScreenGui.ResetOnSpawn = false

local MainFrame = Instance.new("Frame")
MainFrame.Name = "MainFrame"
MainFrame.Size = UDim2.new(0, 455, 0, 665)
MainFrame.Position = UDim2.new(0.25, 0, 0.15, 0)
MainFrame.BackgroundColor3 = Color3.fromRGB(40, 40, 40)
MainFrame.BorderSizePixel = 3
MainFrame.BorderColor3 = Color3.fromRGB(255, 255, 0)
MainFrame.Parent = ScreenGui

local TitleBar = Instance.new("TextLabel")
TitleBar.Name = "TitleBar"
TitleBar.Size = UDim2.new(1, 0, 0, 40)
TitleBar.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
TitleBar.Text = "zGgui V13.2 F3X"
TitleBar.TextColor3 = Color3.fromRGB(255, 255, 255)
TitleBar.Font = Enum.Font.Cartoon
TitleBar.TextSize = 30
TitleBar.Parent = MainFrame

local function createTitleButton(text, callback)
    local btn = Instance.new("TextButton")
	btn.Size = UDim2.new(0, 89, 0, 50)
    btn.Position = UDim2.new(1, -92, 0, 6)
	btn.BackgroundColor3 = Color3.fromRGB(120, 120, 120)
	btn.BorderSizePixel = 2
	btn.BorderColor3 = Color3.fromRGB(0, 0, 0)
	btn.Text = text
	btn.TextColor3 = Color3.fromRGB(0, 0, 0)
	btn.Font = Enum.Font.Cartoon
	btn.TextSize = 15
	btn.Parent = MainFrame

    local corner = Instance.new("UICorner")
    corner.CornerRadius = UDim.new(0, 6)
    corner.Parent = btn

    btn.MouseButton1Click:Connect(function()
        if callback then
            pcall(callback)
        end
    end)

    return btn
end

createTitleButton("Stop Music", function()
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local RequestCommand = ReplicatedStorage:WaitForChild("HDAdminHDClient").Signals.RequestCommandSilent

    RequestCommand:InvokeServer(";unmusic")
end)

local SubTitle = Instance.new("TextLabel")
SubTitle.Name = "SubTitle"
SubTitle.Size = UDim2.new(1, 0, 0, 20)
SubTitle.Position = UDim2.new(0, 0, 0, 40)
SubTitle.BackgroundTransparency = 1
SubTitle.Text = "FE GUI Lua by zGkiddAlt"
SubTitle.TextColor3 = Color3.fromRGB(200, 200, 200)
SubTitle.Font = Enum.Font.Cartoon
SubTitle.TextSize = 25
SubTitle.TextXAlignment = Enum.TextXAlignment.Center
SubTitle.Parent = MainFrame

local UserInputService = game:GetService("UserInputService")

local dragging = false
local dragInput, dragStart, startPos

local function update(input)
	local delta = input.Position - dragStart
	MainFrame.Position = UDim2.new(
		startPos.X.Scale, startPos.X.Offset + delta.X,
		startPos.Y.Scale, startPos.Y.Offset + delta.Y
	)
end

TitleBar.InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		dragging = true
		dragStart = input.Position
		startPos = MainFrame.Position

		input.Changed:Connect(function()
			if input.UserInputState == Enum.UserInputState.End then
				dragging = false
			end
		end)
	end
end)

TitleBar.InputChanged:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
		dragInput = input
	end
end)

UserInputService.InputChanged:Connect(function(input)
	if input == dragInput and dragging then
		update(input)
	end
end)

local ScrollingFrame = Instance.new("ScrollingFrame")
ScrollingFrame.Name = "ScrollingFrame"
ScrollingFrame.Size = UDim2.new(1, -10, 1, -65)
ScrollingFrame.Position = UDim2.new(0, 5, 0, 65)
ScrollingFrame.BackgroundColor3 = Color3.fromRGB(30, 30, 30)
ScrollingFrame.BorderSizePixel = 0
ScrollingFrame.ScrollBarThickness = 10
ScrollingFrame.CanvasSize = UDim2.new(0, 0, 0, 1300)
ScrollingFrame.Parent = MainFrame

local Grid = Instance.new("UIGridLayout")
Grid.CellSize = UDim2.new(0, 140, 0, 50)
Grid.CellPadding = UDim2.new(0, 6, 0, 6)
Grid.FillDirectionMaxCells = 6
Grid.SortOrder = Enum.SortOrder.LayoutOrder
Grid.Parent = ScrollingFrame

function createButton(text, callback)
	local btn = Instance.new("TextButton")
	btn.Size = UDim2.new(0, 140, 0, 50)
	btn.BackgroundColor3 = Color3.fromRGB(120, 120, 120)
	btn.BorderSizePixel = 2
	btn.BorderColor3 = Color3.fromRGB(0, 0, 0)
	btn.Text = text
	btn.TextColor3 = Color3.fromRGB(0, 0, 0)
	btn.Font = Enum.Font.Cartoon
	btn.TextSize = 24
	btn.Parent = ScrollingFrame

	btn.MouseButton1Click:Connect(function()
		if callback then
			callback()
		end
	end)

	return btn
end

